// Extraer datos de los nodos anteriores
const empresa = $('📊 Obtener Perfil Empresa').item.json.records[0]?.fields || {};
const productosData = $('📦 Obtener Servicios Activos').item.json.records || [];
const tema = $('📅 Obtener Próximo Tema Semanal').item.json.records[0];

const servicios = productosData
  .map(p => `- ${p.fields['Nombre de Servicio']}: ${p.fields['Descripción comercial']}`.slice(0, 200))
  .join('\n');

return [
  {
    json: {
      empresa_nombre: empresa['﻿nombre_empresa'] || 'Crating Express',
      empresa_descripcion: empresa['descripción_corta'] || '',
      empresa_propuesta_valor: empresa['propuesta_valor'] || '',
      empresa_ciudad: empresa['ciudad base'] || 'Miami, FL',
      empresa_web: empresa['sitio_web'] || 'cratingexpress.com',
      empresa_telefono: empresa['teléfono'] || '',
      servicios_resumen: servicios,
      tema_id: tema.id,
      tema_texto: tema.fields['Tema'],
      tema_descripcion: tema.fields['Descripcion'] || '',
      tema_palabras_clave: tema.fields['Palabras_Clave'] || '',
      tema_semana: tema.fields['Semana_Numero'] || 1,
      fecha_post: new Date().toISOString().split('T')[0]
    }
  }
];

const aiResponse = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || $input.item.json.choices?.[0]?.message?.content || '{}';
let post;
try {
  post = JSON.parse(aiResponse);
} catch(e) {
  // Intentar extraer JSON si viene con texto extra
  const match = aiResponse.match(/\{[\s\S]*\}/);
  post = match ? JSON.parse(match[0]) : {};
}

const contexto = $('🔧 Preparar Contexto para IA').item.json;

return [{
  json: {
    ...contexto,
    hook_es: post.hook || '',
    mensaje_es: post.mensaje || '',
    cta_es: post.cta || '',
    hashtags: post.hashtags || '',
    texto_canva_titulo: post.texto_canva_titulo || '',
    texto_canva_subtitulo: post.texto_canva_subtitulo || ''
  }
}];

const aiResponse = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || $input.item.json.choices?.[0]?.message?.content || '{}';
let versiones;
try {
  versiones = JSON.parse(aiResponse);
} catch(e) {
  const match = aiResponse.match(/\{[\s\S]*\}/);
  versiones = match ? JSON.parse(match[0]) : {};
}

const prevData = $('🔍 Parsear Post Español').item.json;

return [{
  json: {
    ...prevData,
    post_facebook_en: versiones.facebook || '',
    post_instagram_en: versiones.instagram || '',
    post_linkedin_en: versiones.linkedin || ''
  }
}];

